/*
 * Languages: English (site root), German (/de/), French (/fr/), Spanish (/es/)
 * and Norwegian (/no/). The translated pages are generated by
 * tools/i18n/build.py; this script runs first on every page and
 *   - gives the other scripts E1_T("English text") for their own strings
 *     (from assets/js/i18n-dict.js) and E1_href() for links in the language;
 *   - on a translated page, sends the visitor to the language they chose
 *     before (remembered in this browser) or, on a first visit, to their
 *     browser's language when we have it;
 *   - provides the list for the language switch in the header (main.js).
 */
(function () {
  "use strict";

  var LANGS = [
    { code: "en", name: "English" },
    { code: "de", name: "Deutsch" },
    { code: "fr", name: "Français" },
    { code: "es", name: "Español" },
    { code: "no", name: "Norsk" }
  ];
  var KEY = "e1.lang";
  var PAGES = window.E1_I18N_PAGES || [];
  var DICT = window.E1_I18N_DICT || {};

  var cur = document.documentElement.getAttribute("data-lang") || "en";
  var page = location.pathname.split("/").pop() || "index.html";
  var translated = PAGES.indexOf(page) >= 0;

  function prefix(code) { return code === "en" ? "" : code + "/"; }

  /* A link to one of our pages, in the current language when it exists in it. */
  function href(h) {
    var name = h.split("#")[0].split("?")[0];
    return PAGES.indexOf(name) >= 0 ? prefix(cur) + h : h;
  }

  /* The same page in another language (relative to the site root / base). */
  function hrefFor(code) {
    return (translated ? prefix(code) + page : (code === "en" ? page : prefix(code) + "index.html")) + location.hash;
  }

  function t(s, vars) {
    var out = (DICT[cur] && DICT[cur][s]) || s;
    if (vars) out = out.replace(/\{(\w+)\}/g, function (m, k) { return vars[k] != null ? vars[k] : m; });
    return out;
  }

  function stored() {
    try { return localStorage.getItem(KEY); } catch (e) { return null; }
  }

  function remember(code) {
    try { localStorage.setItem(KEY, code); } catch (e) {}
  }

  function browserLang() {
    var list = navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language || "en"];
    for (var i = 0; i < list.length; i++) {
      var l = String(list[i]).toLowerCase().slice(0, 2);
      if (l === "nb" || l === "nn") l = "no";
      if (l === "en" || l === "de" || l === "fr" || l === "es" || l === "no") return l;
    }
    return "en";
  }

  window.E1_LANG = cur;
  window.E1_LANGS = LANGS;
  window.E1_T = t;
  window.E1_href = href;
  window.E1_hrefFor = hrefFor;
  window.E1_rememberLang = remember;

  // Send the visitor to their language (only between our translated pages).
  if (translated) {
    // A remembered choice always wins. Without one, only the English pages
    // follow the browser's language: a shared link to /de/ stays German.
    var want = stored() || (cur === "en" ? browserLang() : cur);
    if (want !== cur && LANGS.some(function (l) { return l.code === want; })) {
      location.replace(new URL(hrefFor(want), document.baseURI).href);
    }
  }
})();
